import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-11-21 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-11-21 -- Ceph Performance Meeting","date":"2019-11-21T00:00:00.000Z","updated":"2019-11-26T00:00:00.000Z","tags":["Ceph性能优化","Ceph存储系统","CRUSH算法","分布式存储","上线测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-21_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-11-21_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-11-21_-_-_Ceph_Performance_Meeting.md"};function n(o,e,s,_,h,c){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><p><strong>新提交的PR</strong>:</p><ul><li>David Zetland的PR针对upnot balancer逻辑改进，以提升速度和优化性能。</li><li>MDS PR涉及CPU亲和性设置。</li><li>Adam的PR针对字符串优化，使用string_view或其他方法。</li></ul></li><li><p><strong>已关闭或更新的PR</strong>:</p><ul><li>Neha的快速修复，禁用arm range合并。</li><li>调整默认的max MF条目每请求的合并。</li><li>用户空间拉取事件的PR因内核实验性内容被关闭。</li><li>避免OSD消耗map的PR被关闭，无具体解释。</li><li>PG autoscaler默认PG数216已批准。</li><li>Eric的OSD中GW CLS代码的过滤改进已更新。</li></ul></li><li><p><strong>其他讨论</strong>:</p><ul><li>4K min_alloc_size的讨论，涉及SSD和NVMe驱动器的性能和空间放大问题。</li><li>混合工作负载处理，特别是对RGW工作负载的影响。</li><li>新Intel节点的测试，包括读写性能和I/O操作。</li></ul></li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ul><li><strong>性能优化</strong>: 重点讨论了upnot balancer逻辑改进和字符串优化方法。</li><li><strong>硬件兼容性</strong>: 讨论了4K min_alloc_size在不同类型存储设备上的表现和优化策略。</li><li><strong>系统配置</strong>: 涉及MDS的CPU亲和性设置和OSD的过滤改进。</li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续进行4K min_alloc_size测试，特别是对RGW工作负载的影响。</li><li>对新的Intel节点进行优化配置，以提高性能。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>对4K min_alloc_size进行更多测试，包括RGW工作负载的性能评估。</li><li>继续优化新的Intel节点的配置，以达到更好的读写性能和I/O操作。</li><li>下周会议将继续讨论相关PR和配置优化。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中提到一些技术细节和测试结果，需要进一步分析和验证。</li><li>对于混合工作负载的处理，需要找到更通用的解决方案。</li></ul>',11)])])}const p=l(r,[["render",n]]);export{u as __pageData,p as default};
